INSERT INTO "jobs" VALUES('wanted','https://www.wanted.co.kr/wd/369513','{"collected_at":"2026-11-22T00:00:35.693603+00:00","company":"리얼월드","deadline":"","description":"HRM - 인사 제도 전반의 운영 및 개선 - 성과관리 및 평가 프로세스 운영 - 보상 및 복리후생 제도 운영 지원 - HR 데이터 분석 및 인사이트 도출 Organization & Culture - 조직문화 및 핵심가치 내재화 프로그램 기획·운영 - 온보딩 프로그램 운영 및 구성원 경험(Employee Experience) 개선 - 조직 진단 및 조직개발(OD) 활동 지원 - 구성원 Engagement 프로그램 기획·운영 - 리더 및 구성원 대상 HR 파트너 역할 수행 HR Operations - 입·퇴사 및 인사 행정 전반 관리 - 근로계약 및 인사 문서 관리 - 인사 규정 및 정책 수립·개선 - 노동관계법 준수 및 노무 이슈 대응 - 외부 노무사 및 유관 파트너사 협업 Compensation & Benefits - 급여 및 복리후생 운영 지원 - 연봉 및 보상 프로세스 운영 - 보상 데이터 및 인력 지표 관리 HR, 인사담당, 노무·노사, 조직문화","employment_type":"regular","experience":"경력 3년+ / 정규직","keyword":"HR","link":"https://www.wanted.co.kr/wd/369513","location":"한국 서울 강남구 서울 강남구 테헤란로 415, L7강남 5,7층","matched_keywords":["HR","인사","조직문화"],"site":"wanted","source_url":"https://www.wanted.co.kr/api/chaos/search/v1/position?query=HR&country=kr&years=-1&locations=all&sort=job.recommend_order&limit=20&offset=0","title":"HR Manager [경력 3년+ / 정규직]"}','3fc0e3b3233bbf174f414f9ba7d34291cd7c3571b3b78c3e0eb10831a62d75c9','2026-10-17T17:35:26+00:00','2026-11-22T00:01:12+00:00','2026-10-17T17:35:26+00:00');
